import{_ as r,o,c as n,ag as s}from"./chunks/framework.QfQ7DfGu.js";const u=JSON.parse('{"title":"LoongArch UEFI","description":"","frontmatter":{"title":"LoongArch UEFI","outline":"deep"},"headers":[],"relativePath":"toolchain/uefi.md","filePath":"toolchain/uefi.md"}'),a={name:"toolchain/uefi.md"};function e(g,t,i,l,d,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="uefi" tabindex="-1">UEFI <a class="header-anchor" href="#uefi" aria-label="Permalink to &quot;UEFI&quot;">​</a></h1><p>UEFI（Unified Extensible Firmware Interface，统一可扩展固件接口）是<strong>传统BIOS的现代化替代方案</strong>，是一种定义操作系统与系统固件之间接口的标准，旨在解决传统BIOS的局限性（如16位架构、2TB硬盘限制、启动慢等），为现代计算设备提供更强大、更灵活的固件支持。自2005年由英特尔联合多家厂商成立UEFI论坛并推广以来，UEFI已成为PC、嵌入式系统等领域的主流固件接口，其设计理念和功能特性深刻影响着现代计算机的启动流程与硬件管理。</p><h2 id="一、uefi的基本概念与产生背景" tabindex="-1"><strong>一、UEFI的基本概念与产生背景</strong> <a class="header-anchor" href="#一、uefi的基本概念与产生背景" aria-label="Permalink to &quot;**一、UEFI的基本概念与产生背景**&quot;">​</a></h2><p>UEFI的前身是英特尔1998年推出的<strong>EFI（Extensible Firmware Interface，可扩展固件接口）</strong>，最初用于安腾处理器平台，旨在替代传统BIOS的16位实模式限制。2005年，英特尔将EFI贡献给行业，联合AMD、微软、戴尔等11家公司成立<strong>UEFI论坛</strong>，将EFI发展为跨平台的**统一可扩展固件接口（UEFI）**标准，新增了安全启动、图形界面、网络功能等现代特性。</p><p>传统BIOS（Basic Input/Output System）诞生于1980年代，采用16位实模式运行，存在<strong>1MB内存寻址限制</strong>、<strong>2TB硬盘容量上限</strong>、<strong>启动流程串行效率低</strong>等固有缺陷，无法满足现代硬件（如64位CPU、大容量SSD、多核处理器）的需求。UEFI的出现正是为了解决这些问题，其设计目标包括：</p><ul><li>支持64位架构，突破内存寻址限制；</li><li>兼容大容量硬盘（超过2TB）；</li><li>提升启动速度（并行初始化硬件）；</li><li>增强安全性（如安全启动）；</li><li>提供更友好的用户界面（图形化、鼠标支持）。</li></ul><h2 id="二、uefi的核心特性与优势" tabindex="-1"><strong>二、UEFI的核心特性与优势</strong> <a class="header-anchor" href="#二、uefi的核心特性与优势" aria-label="Permalink to &quot;**二、UEFI的核心特性与优势**&quot;">​</a></h2><p>UEFI之所以能替代传统BIOS，在于其<strong>现代化的架构设计</strong>和<strong>丰富的功能特性</strong>，主要包括以下几个方面：</p><h3 id="_1-架构与性能-64位支持与并行初始化" tabindex="-1"><strong>1. 架构与性能：64位支持与并行初始化</strong> <a class="header-anchor" href="#_1-架构与性能-64位支持与并行初始化" aria-label="Permalink to &quot;**1. 架构与性能：64位支持与并行初始化**&quot;">​</a></h3><p>UEFI采用<strong>模块化、C语言风格</strong>的架构，摆脱了传统BIOS的16位汇编限制，支持32位或64位保护模式运行，充分利用现代CPU的性能。其<strong>并行初始化机制</strong>是提升启动速度的关键——传统BIOS按顺序检测硬件（如CPU→内存→硬盘），而UEFI可同时初始化多个硬件组件（如CPU、内存、硬盘、USB控制器），大幅缩短开机自检（POST）时间。例如，中提到，UEFI的并行启动机制让启动速度显著提升，而提到瑞芯微RK平台的UEFI开发支持进一步优化了这一过程。</p><h3 id="_2-硬盘支持-gpt分区表与大容量存储" tabindex="-1"><strong>2. 硬盘支持：GPT分区表与大容量存储</strong> <a class="header-anchor" href="#_2-硬盘支持-gpt分区表与大容量存储" aria-label="Permalink to &quot;**2. 硬盘支持：GPT分区表与大容量存储**&quot;">​</a></h3><p>UEFI强制要求使用<strong>GPT（GUID Partition Table，全局唯一标识分区表）</strong>，取代了传统BIOS的MBR（Master Boot Record，主引导记录）分区表。GPT的优势在于：</p><ul><li><strong>支持超大容量硬盘</strong>：理论上可支持18EB（1EB=1024PB）的硬盘，彻底解决了MBR的2TB限制；</li><li><strong>多分区支持</strong>：允许创建128个主分区（MBR仅支持4个），满足现代用户对多系统、多分区存储的需求；</li><li><strong>可靠性更高</strong>：GPT使用CRC校验和记录分区信息，避免MBR因分区表损坏导致的硬盘无法识别问题。</li></ul><h3 id="_3-安全性-安全启动-secure-boot" tabindex="-1"><strong>3. 安全性：安全启动（Secure Boot）</strong> <a class="header-anchor" href="#_3-安全性-安全启动-secure-boot" aria-label="Permalink to &quot;**3. 安全性：安全启动（Secure Boot）**&quot;">​</a></h3><p>UEFI的**安全启动（Secure Boot）**是其最核心的安全特性，旨在防止恶意软件在启动过程中加载（如bootkit）。其工作原理如下：</p><ul><li><strong>密钥数据库</strong>：主板出厂时预装<strong>平台密钥（PK）</strong>、<strong>可信软件发行商密钥（KEK）<strong>和</strong>操作系统密钥（db）</strong>，形成“可信根”；</li><li><strong>链式验证</strong>：启动时，UEFI会验证引导程序（如Windows Boot Manager、Grub）的数字签名，确保其由可信密钥签发；只有验证通过的程序才能加载，否则拒绝执行；</li><li><strong>黑名单机制</strong>：被黑客篡改的程序会被加入<strong>禁止列表（dbx）</strong>，永久禁止启动。</li></ul><p>安全启动有效抵御了“开机前攻击”，是现代操作系统（如Windows 8及以上、Linux发行版）的必备安全功能。</p><h3 id="_4-用户体验-图形化界面与网络支持" tabindex="-1"><strong>4. 用户体验：图形化界面与网络支持</strong> <a class="header-anchor" href="#_4-用户体验-图形化界面与网络支持" aria-label="Permalink to &quot;**4. 用户体验：图形化界面与网络支持**&quot;">​</a></h3><p>UEFI提供了<strong>图形化的设置界面</strong>，支持鼠标操作和中文显示，取代了传统BIOS的“蓝底白字”命令行界面。用户可通过图形界面轻松调整启动顺序、设置超频参数、查看硬件状态（如CPU温度、风扇转速），极大提升了操作便利性。</p><p>此外，UEFI内置<strong>网络功能</strong>，支持远程诊断、网络启动（如PXE、HTTP启动），方便系统安装、更新和修复。例如，提到，UEFI的网络启动功能可用于嵌入式设备的远程维护。</p><h3 id="_5-扩展性-模块化驱动与动态加载" tabindex="-1"><strong>5. 扩展性：模块化驱动与动态加载</strong> <a class="header-anchor" href="#_5-扩展性-模块化驱动与动态加载" aria-label="Permalink to &quot;**5. 扩展性：模块化驱动与动态加载**&quot;">​</a></h3><p>UEFI的<strong>模块化驱动模型</strong>是其另一大优势。驱动程序以<strong>EFI驱动镜像</strong>的形式存在，可动态加载到内存中，无需修改固件本身。例如，当用户插入一个新的USB设备时，UEFI可自动加载对应的USB驱动，无需重启系统。这种模块化设计使得UEFI的扩展性极强，能适应不断更新的硬件（如新型显卡、网卡、存储设备）。</p><h2 id="三、uefi与传统bios的核心区别" tabindex="-1"><strong>三、UEFI与传统BIOS的核心区别</strong> <a class="header-anchor" href="#三、uefi与传统bios的核心区别" aria-label="Permalink to &quot;**三、UEFI与传统BIOS的核心区别**&quot;">​</a></h2><p>UEFI与传统BIOS的差异主要体现在<strong>架构、性能、硬盘支持、安全性、用户体验</strong>等方面，以下是具体对比：</p><table tabindex="0"><thead><tr><th><strong>特性</strong></th><th><strong>传统BIOS</strong></th><th><strong>UEFI</strong></th></tr></thead><tbody><tr><td><strong>架构模式</strong></td><td>16位实模式，1MB内存寻址</td><td>32/64位保护模式，支持大内存</td></tr><tr><td><strong>硬盘支持</strong></td><td>MBR分区表，最大2TB，4个主分区</td><td>GPT分区表，支持18EB，128个主分区</td></tr><tr><td><strong>启动速度</strong></td><td>串行初始化，启动慢（数十秒）</td><td>并行初始化，启动快（数秒）</td></tr><tr><td><strong>安全性</strong></td><td>无安全启动，易受bootkit攻击</td><td>支持安全启动，防止恶意代码加载</td></tr><tr><td><strong>用户界面</strong></td><td>蓝底白字，命令行，仅键盘操作</td><td>图形化界面，支持鼠标、中文</td></tr><tr><td><strong>扩展性</strong></td><td>驱动需硬编码，扩展性差</td><td>模块化驱动，动态加载，扩展性强</td></tr></tbody></table><h2 id="四、uefi的应用场景" tabindex="-1"><strong>四、UEFI的应用场景</strong> <a class="header-anchor" href="#四、uefi的应用场景" aria-label="Permalink to &quot;**四、UEFI的应用场景**&quot;">​</a></h2><p>UEFI的应用场景已从传统PC扩展至<strong>嵌入式系统、服务器、移动设备</strong>等领域，主要包括：</p><h3 id="_1-pc与服务器领域" tabindex="-1"><strong>1. PC与服务器领域</strong> <a class="header-anchor" href="#_1-pc与服务器领域" aria-label="Permalink to &quot;**1. PC与服务器领域**&quot;">​</a></h3><p>UEFI是<strong>现代PC的主流固件接口</strong>，几乎所有2020年以后生产的电脑（包括笔记本、台式机）都采用UEFI。服务器领域，UEFI的<strong>安全启动</strong>、<strong>大容量硬盘支持</strong>、<strong>远程管理</strong>等特性，使其成为数据中心服务器的首选固件接口。</p><h3 id="_2-嵌入式系统领域" tabindex="-1"><strong>2. 嵌入式系统领域</strong> <a class="header-anchor" href="#_2-嵌入式系统领域" aria-label="Permalink to &quot;**2. 嵌入式系统领域**&quot;">​</a></h3><p>UEFI在嵌入式系统中的应用日益广泛，尤其是<strong>智能硬件、工业控制、边缘计算</strong>等场景。例如：</p><ul><li><strong>瑞芯微RK平台</strong>：UEFI被深度集成到Linux SDK中，支撑智能终端、边缘计算设备、工业控制单元等产品的启动与硬件管理，支持Android Boot与Grub双启动方式，满足多系统需求；</li><li><strong>NVIDIA Orin平台</strong>：UEFI的动态协议支持（如<code>EFI_DRIVER_BINDING_PROTOCOL</code>）满足车载环境中的热插拔传感器、车载以太网等需求，其安全启动（三级验证链）符合车规级ISO 21434标准；</li><li><strong>Xilinx Versal平台</strong>：虽然Versal选择了U-Boot作为引导程序，但UEFI的<strong>标准化驱动模型</strong>仍被视为未来嵌入式系统的潜在选择，尤其是在需要动态硬件识别的场景中。</li></ul><h3 id="_3-移动设备领域" tabindex="-1"><strong>3. 移动设备领域</strong> <a class="header-anchor" href="#_3-移动设备领域" aria-label="Permalink to &quot;**3. 移动设备领域**&quot;">​</a></h3><p>部分移动设备（如手机、平板）也开始采用UEFI替代传统Bootloader（如LK）。例如，高通从MSM8998开始使用UEFI作为手机的Bootloader，其<strong>模块化驱动模型</strong>和<strong>安全启动</strong>特性，满足了手机设备对多样化硬件（如5G modem、高刷新率屏幕）的支持需求。</p><h2 id="五、uefi的最新进展-2025-2026年" tabindex="-1"><strong>五、UEFI的最新进展（2025-2026年）</strong> <a class="header-anchor" href="#五、uefi的最新进展-2025-2026年" aria-label="Permalink to &quot;**五、UEFI的最新进展（2025-2026年）**&quot;">​</a></h2><p>2025年以来，UEFI的发展重点在于<strong>嵌入式系统优化</strong>、<strong>安全增强</strong>和<strong>多平台兼容</strong>，主要进展包括：</p><h3 id="_1-嵌入式系统优化-瑞芯微rk平台" tabindex="-1"><strong>1. 嵌入式系统优化：瑞芯微RK平台</strong> <a class="header-anchor" href="#_1-嵌入式系统优化-瑞芯微rk平台" aria-label="Permalink to &quot;**1. 嵌入式系统优化：瑞芯微RK平台**&quot;">​</a></h3><p>2026年1月，瑞芯微发布了<strong>RK3588 Linux SDK</strong>，进一步完善了UEFI的开发支持。该SDK提供了<strong>两种编译方式</strong>（直接使用uefi目录脚本或SDK根目录build.sh脚本），简化了固件编译流程；同时，支持<strong>EMMC、SPI Nor Flash</strong>等多种存储介质的烧录，满足不同嵌入式设备的需求。此外，RK平台的UEFI支持<strong>显示配置</strong>（如HDMI、DP）、<strong>USB配置</strong>（如USB2.0、Type-C）等定制化功能，提升了嵌入式设备的硬件适配能力。</p><h3 id="_2-安全增强-nvidia-orin的车规级应用" tabindex="-1"><strong>2. 安全增强：NVIDIA Orin的车规级应用</strong> <a class="header-anchor" href="#_2-安全增强-nvidia-orin的车规级应用" aria-label="Permalink to &quot;**2. 安全增强：NVIDIA Orin的车规级应用**&quot;">​</a></h3><p>2025年6月，NVIDIA在Orin平台上强化了UEFI的<strong>安全启动</strong>功能，采用<strong>三级验证链</strong>（每级验证下一级数字签名），符合车规级ISO 21434标准，有效防止恶意代码注入。此外，Orin的UEFI支持<strong>PXE网络启动</strong>（HTTP/TFTP），方便车载设备的远程维护。</p><h3 id="_3-多平台兼容-arm生态的扩展" tabindex="-1"><strong>3. 多平台兼容：ARM生态的扩展</strong> <a class="header-anchor" href="#_3-多平台兼容-arm生态的扩展" aria-label="Permalink to &quot;**3. 多平台兼容：ARM生态的扩展**&quot;">​</a></h3><p>随着ARM架构进入PC、服务器等传统x86领域（如苹果M系列芯片、华为鲲鹏920），UEFI的<strong>标准化接口</strong>成为ARM生态的必备组件。例如，苹果M系列芯片的Mac电脑采用UEFI作为固件接口，支持<strong>安全启动</strong>、<strong>图形化界面</strong>等功能，兼容macOS和Windows操作系统。</p><h2 id="六、uefi的未来趋势" tabindex="-1"><strong>六、UEFI的未来趋势</strong> <a class="header-anchor" href="#六、uefi的未来趋势" aria-label="Permalink to &quot;**六、UEFI的未来趋势**&quot;">​</a></h2><p>UEFI的未来发展方向主要集中在以下几个方面：</p><h3 id="_1-更广泛的应用场景" tabindex="-1"><strong>1. 更广泛的应用场景</strong> <a class="header-anchor" href="#_1-更广泛的应用场景" aria-label="Permalink to &quot;**1. 更广泛的应用场景**&quot;">​</a></h3><p>随着物联网（IoT）、边缘计算、智能汽车等领域的快速发展，UEFI的<strong>模块化驱动模型</strong>、<strong>安全启动</strong>、<strong>远程管理</strong>等特性，将使其成为这些领域的首选固件接口。例如，智能汽车的<strong>OTA升级</strong>、<strong>车载娱乐系统</strong>等场景，都需要UEFI的支持。</p><h3 id="_2-更强的兼容性" tabindex="-1"><strong>2. 更强的兼容性</strong> <a class="header-anchor" href="#_2-更强的兼容性" aria-label="Permalink to &quot;**2. 更强的兼容性**&quot;">​</a></h3><p>UEFI将进一步提升对** legacy 硬件**（如传统BIOS设备）的兼容性，通过<strong>兼容性支持模块（CSM）</strong>，允许用户在UEFI模式下启动传统BIOS设备，避免因硬件升级导致的兼容性问题。</p><h3 id="_3-更智能的功能" tabindex="-1"><strong>3. 更智能的功能</strong> <a class="header-anchor" href="#_3-更智能的功能" aria-label="Permalink to &quot;**3. 更智能的功能**&quot;">​</a></h3><p>UEFI将融入更多<strong>智能化特性</strong>，如<strong>机器学习-based 硬件检测</strong>（自动识别新硬件并加载驱动）、<strong>预测性维护</strong>（通过硬件状态监测提前预警故障）等，提升设备的可靠性和用户体验。</p><h2 id="总结" tabindex="-1"><strong>总结</strong> <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**&quot;">​</a></h2><p>UEFI作为传统BIOS的现代化替代方案，通过其<strong>64位架构</strong>、<strong>GPT分区表</strong>、<strong>安全启动</strong>、<strong>图形化界面</strong>等特性，解决了传统BIOS的固有缺陷，成为现代计算设备的主流固件接口。其在<strong>PC、嵌入式系统、服务器</strong>等领域的广泛应用，充分体现了其<strong>灵活性</strong>和<strong>扩展性</strong>。随着技术的不断发展，UEFI将继续演进，适应更多新兴场景的需求，为现代计算提供更强大的固件支持。</p>',52)])])}const E=r(a,[["render",e]]);export{u as __pageData,E as default};
